data.code:
// String
<Welcome name="Alice" />

// Number
<Age value={25} />

// Boolean
<IsActive isActive={true} />

// Object
<User info={{ name: 'Alice', age: 25 }} />

// Array
<Colors palette={['red', 'green', 'blue']} />

// Function
<Button onClick={() => alert('Clicked!')} />

// Dot notation
function UserCard(props) {
  return <h2>{props.name}</h2>;
}

// Destructuring in parameters
function UserCard({ name, email }) {
  return (
    <div>
      <h2>{name}</h2>
      <p>{email}</p>
    </div>
  );
}

// WRONG — mutating props
function Counter(props) {
  props.count = props.count + 1; // Do not do this
  return <p>{props.count}</p>;
}

// CORRECT — props are read-only data
function Counter({ count }) {
  return <p>Count: {count}</p>;
}

// Parent passes count as a prop and updates it with its own state
<Counter count={5} />
